cm = Path("codemagic.yaml")
if cm.exists():
    y = cm.read_text(encoding="utf-8", errors="ignore")
    y = re.sub(r'APP_VERSION:\s*["\'][0-9]+\.[0-9]+\.[0-9]+["\']', f'APP_VERSION: "{APP_VERSION}"', y)
    y = re.sub(r'success:\s*true', 'success: false', y)
    cm.write_text(y, encoding="utf-8")
    print(f"OK: APP_VERSION impostata a {APP_VERSION} e email successo disattivate")
else:
    print("ATTENZIONE: codemagic.yaml non trovato, aggiorna APP_VERSION manualmente")
